/* If any setup material is defined in the request for SN transfer, 
checks to make sure the entire setup material is being consumed. */

(
  $output := $state.context.REQUEST.DATA.output;
  $inputs := $state.context.REQUEST.DATA.inputs;
  $materials := productionSetupOutput.edges.node.workunit.productionSetupMaterials.edges.node;
  $boms := productionSetupOutput.edges.node.productionSetupBoms.edges.node;
  $exists($output.serialNumber.setupMaterialId)?
  $inputs[$exists(setupMaterialId)].(
    $materialId := setupMaterialId;
    $material := $materials[id=$materialId];
    $bom := $boms[componentProductId = $material.productId];
    $bom.consumptionTypeId = "standard" ?
    quantity * $bom.standardUsage = $material.quantity : true
  ) 
~> $reduce(function($i, $j){$i and $j}) ~> $not  : false
)

(
  $boms := productionSetupOutput.edges.node.productionSetupBoms.edges.node[allowOverConsumption = false];
  $materials := productionSetupOutput.edges.node.workunit.productionSetupMaterials.edges.node;
  $output := $state.context.REQUEST.DATA.output;
  $inputs := $state.context.REQUEST.DATA.inputs;
  $quantity := $coalesce([$output.producedQuantity, $output.scrappedQuantity, $output.suspectQuantity]);

  $boms.(
    $productId := componentProductId;
    $setupMaterialId := $materials[productId = $productId].id;
    consumptionTypeId = "standard" ?
      standardUsage * $quantity > $sum($materials[productId = $productId].quantity) 
    : consumptionTypeId = "actual" ? $sum($inputs[setupMaterialId = $setupMaterialId].quantity) > $sum($materials[productId = $productId].quantity) 
    : consumptionTypeId = "none" ? false  
  )
) 
~> $reduce(function($i,$j){$i and $j})

