  $productionSetupOperators := productionSetupOutput.edges.node.workunit.productionSetupOperators.edges.node;
  $productionHistoryId := $cuid();
  $currentProcessSteps := productionSetupOutput.edges.node.productionSetupOutputSteps.edges.node;
  
  $totalProducedQuantity := $defaultTo($productionSetupOutput.dist.productionHistories.edges.node._aggregate.quantity.sum, 0) + $coalesce([ $output.producedQuantity,  $output.suspectQuantity, 0]);
  $totalScrappedQuantity := $defaultTo($productionSetupOutput.dist.scrap.edges.node._aggregate.quantity.sum + $output.scrappedQuantity, 0);


  $payloadProductionHistoryInputs := $inputs.(
        $setupMaterialId := setupMaterialId;
        {
          "create":{
            "id": $cuid(),
            "productionHistoryId": $productionHistoryId,
            "quantity": quantity,
            "serial": serial,
            "processId": $productionSetupOutput.dist.workOrderProcess.processId,
            "productId": productId,
            "workOrderProcessDistributionId": $productionSetupOutput.dist.id
        }
      }
    );

  {
    "payloadProductionHistory": {
      "create":{
        "id": $productionHistoryId,
        "quantity": $output.producedQuantity,
        "serial": $exists($output.serialNumber.setupMaterialId) ? $productionSetupMaterials[id=$output.serialNumber.setupMaterialId].$coalesce([serial, number]),
        "occurAt": $local.time,
        "workunitId": $productionSetupOutput.workunit.id,
        "productionRunId": $productionSetupOutput.workunit.currentProductionRunId,
        "productId": $product,
        "suspect": $output.suspectQuantity>0,
        "scrap": $output.scrappedQuantity>0,
        "workOrderProcessDistributionId": $productionSetupOutput.dist.id
      }
    },
    "payloadProductionHistoryInputs":[ $payloadProductionHistoryInputs],
    "payloadUpdateSetupMaterials":[ $inputs.(
      $setupMaterialId := $.id;
      $material := $productionSetupMaterials[id = $setupMaterialId];
      $bom := $boms[componentProductId = $material.productId];
      $bom.consumptionTypeId = "none" ? [] : {
        "where": {
          "id": $setupMaterialId
        },
        "update": {
          "quantity": $material.quantity - quantity
        }
      }
    )],
    "payloadUpdateProductionSetupOutput":{
      "update": {
        "produced": $totalProducedQuantity,
        "scrapped": $totalScrappedQuantity
      },
      "where": {
        "id": $productionSetupOutput.id
      }
    },
    "payloadProductionHistoryOperator":[ $productionSetupOperators.{
      "create": {
        "operatorId": $.userId,
        "productionHistoryId": $productionHistoryId
      }
    }],
    "payloadStepHistory": [$currentProcessSteps.{
      "create": $~>|$|
        (
          $crrBomProductId := productStrategyProcessBom.componentProductId;
          {
            "productionHistoryId": $productionHistoryId,
            "productionHistoryInputId": $payloadProductionHistoryInputs.create[productId=$crrBomProductId].id
          }
        ), 
        ["id", "productionSetupOutputStepStatusId", "productionSetupOutputStepId", "productStrategyProcessBom"] 
      | 
    }],
    "payloadCurrentStep": [$currentProcessSteps#$i.{
      "where":{ "id": id},
      "update": {
        "startAt": $i = 0? $moment().format() : null,
        "endAt": null,
        "value": null,
        "productionSetupOutputStepStatusId": "pending"
      }
    }],
    "payloadDistribution":[
      {
        "where":{ "id": $productionSetupOutput.dist.id},
        "update":{
          "producedQuantity": $totalProducedQuantity
        }
      }
    ]
  }
  
)

